let key = SymmetricKey(data: try Data(contentsOf: keyURL))   // stable, from Keychain/config

func seal(_ session: Session) throws -> String {
    let data = try JSONEncoder().encode(session)
    let mac = HMAC<SHA256>.authenticationCode(for: data, using: key)
    return Data(data).base64EncodedString() + "." + Data(mac).base64EncodedString()
}

